export function splitLines(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

/**
 * Parses the whole input. Returns the declared tasks in declaration order, a
 * map from a name to the set of names it depends on, and the graph edges.
 */
export function parseGraph(text) {
  const costs = new Map()
  const deps = new Map()
  const used = []

  const lines = splitLines(text)
  for (let index = 0; index < lines.length; index += 1) {
    const lineNumber = index + 1
    const line = lines[index].trim()
    if (line === '' || line.startsWith('#')) continue
    const words = line.split(/\s+/)

    if (words[0] === 'task') {
      if (words.length !== 3) {
        throw new FailureError(`line ${lineNumber}: expected task <name> <cost>`)
      }
      const [, name, cost] = words
      checkName(lineNumber, name)
      if (!COST.test(cost)) {
        throw new FailureError(`line ${lineNumber}: cost must be a non-negative integer`)
      }
      if (costs.has(name)) {
        throw new FailureError(`line ${lineNumber}: task ${name} is declared twice`)
      }
      costs.set(name, Number(cost))
      if (!deps.has(name)) deps.set(name, new Set())
    } else if (words[0] === 'dep') {
      if (words.length < 3) {
        throw new FailureError(`line ${lineNumber}: expected dep <name> <dependency>...`)
      }
      for (const word of words.slice(1)) checkName(lineNumber, word)
      const name = words[1]
      used.push(name)
      if (!deps.has(name)) deps.set(name, new Set())
      for (const dependency of words.slice(2)) {
        used.push(dependency)
        deps.get(name).add(dependency)
      }
