{"file_path":"src/graph.js","content":"/**
 * Turns a parsed graph into the derived quantities the three reports need:
 * cycle detection, waves, start and finish times, and chain priorities.
 */

import { CycleError } from './errors.js'

/**
 * Depth-first search from each task in ascending name order, walking each
 * task's dependencies in ascending name order. Throws on the first cycle.
 */
export function checkAcyclic({ names, dependencies }) {
  const WHITE = 0
  const GREY = 1
  const BLACK = 2
  const colour = new Map(names.map((name) => [name, WHITE]))

  for (const root of names) {
    if (colour.get(root) !== WHITE) continue
    colour.set(root, GREY)
    const path = [root]
    const frames = [{ node: root, index: 0 }]
    while (frames.length > 0) {
      const frame = frames[frames.length - 1]
      const edges = dependencies.get(frame.node)
      if (frame.index < edges.length) {
        const next = edges[frame.index]
        frame.index += 1
        if (colour.get(next) === GREY) {
          const cycle = path.slice(path.indexOf(next))
          cycle.push(next)
          throw new CycleError(cycle)
        }
        if (colour.get(next) === WHITE) {
          colour.set(next, GREY)
          path.push(next)
          frames.push({ node: next, index: 0 })
        }
      } else {
        colour.set(frame.node, BLACK)
        path.pop()
        frames.pop()
      }
    }
  }
}

/** A topological order of an acyclic graph: dependencies before dependents. */
export function topologicalOrder({ names, dependencies }) {
  const order = []
  const done = new Set()
  let remaining = names.slice()
  while (remaining.length > 0) {
    const next = []
    for (const name of remaining) {
      if (dependencies.get(name).every((dep) => done.has(dep))) order.push(name)
      else next.push(name)
    }
    for (const name of order) done.add(name)
    remaining = next
  }
  return order
}

/** The wave, start time and finish time of every task. */
export function schedule(graph) {
  const { costs, dependencies } = graph
  const order = topologicalOrder(graph)
  const depth = new Map()
  const start = new Map()
  const finish = new Map()
  for (const name of order) {
    let d = 0
    let s = 0
    let any = false
    for (const dep of dependencies.get(name)) {
      any = true
      d = Math.max(d, depth.get(dep) + 1)
      s = Math.max(s, finish.get(dep))
    }
    if (!any) {
      d = 0
      s = 0
    }
    depth.set(name, d)
    start.set(name, s)
    finish.set(name, s + costs.get(name))
  }
  let total = 0
  for (const value of finish.values()) total = Math.max(total, value)
  return { depth, start, finish, total, order }
}

/** The cost of the longest chain that begins at each task, counting its own. */
export function priorities(graph) {
  const { names, costs, dependencies } = graph
  const dependents = new Map(names.map((name) => [name, []]))
  for (const name of names) {
    for (const dep of dependencies.get(name)) dependents.get(dep).push(name)
  }
  const order = topologicalOrder(graph)
  const priority = new Map()
  for (let i = order.length - 1; i >= 0; i -= 1) {
    const name = order[i]
    let best = 0
    for (const child of dependents.get(name)) best = Math.max(best, priority.get(child))
    priority.set(name, costs.get(name) + best)
  }
  return priority
}
"}

