{"file_path":"src/pack.js","content":"/**
 * The list scheduler behind `pack`: greedy on the longest remaining chain,
 * ties broken by ascending name, onto the free worker of smallest index.
 */

import { priorities } from './graph.js'

export function pack(graph, workerCount) {
  const { names, costs, dependencies } = graph
  const priority = priorities(graph)
  const freeAt = new Array(workerCount).fill(0)
  const runs = Array.from({ length: workerCount }, () => [])
  const finish = new Map()
  const pending = new Set(names)

  let time = 0
  let makespan = 0
  while (pending.size > 0) {
    for (;;) {
      const worker = freeAt.findIndex((at) => at <= time)
      if (worker === -1) break
      let chosen = null
      for (const name of names) {
        if (!pending.has(name)) continue
        const ready = dependencies.get(name).every((dep) => finish.has(dep) && finish.get(dep) <= time)
        if (!ready) continue
        if (chosen === null || priority.get(name) > priority.get(chosen)) chosen = name
      }
      if (chosen === null) break
      const end = time + costs.get(chosen)
      pending.delete(chosen)
      finish.set(chosen, end)
      freeAt[worker] = end
      runs[worker].push({ name: chosen, start: time, finish: end })
      if (end > makespan) makespan = end
    }
    if (pending.size === 0) break
    let next = null
    for (const at of freeAt) {
      if (at > time && (next === null || at < next)) next = at
    }
    if (next === null) break
    time = next
  }

  return { runs, makespan }
}
"}

