/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import { readFileSync } from 'node:fs'
import { FailureError } from './errors.js'
import { parseGraph } from './parse.js'
import { checkAcyclic, schedule } from './graph.js'
import { pack } from './pack.js'

const USAGE = 'usage: cli.js waves|explain|pack <workers>'
const WORKERS = /^[1-9][0-9]*$/

function parseArguments(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!WORKERS.test(argv[1])) {
      throw new FailureError('workers must be a positive integer')
    }
    return { mode: 'pack', workers: Number(argv[1]) }
  }
  throw new FailureError(USAGE)
}

function readStdin() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

function renderWaves(graph) {
  const { depth, total } = schedule(graph)
  const waves = []
  for (const name of graph.names) {
    const d = depth.get(name)
    while (waves.length <= d) waves.push([])
    waves[d].push(name)
  }
  const lines = waves.map((wave, index) => `wave ${index}: ${wave.join(' ')}`)
  lines.push(`total ${total}`)
  return lines
}

function renderExplain(graph) {
  const { depth, start, finish, total } = schedule(graph)
  const lines = graph.names.map(
    (name) => `${name} start=${start.get(name)} finish=${finish.get(name)} depth=${depth.get(name)}`,
  )
  lines.push(`total ${total}`)
  return lines
}

function renderPack(graph, workers) {
  const { runs, makespan } = pack(graph, workers)
  const lines = runs.map(
    (runList, index) =>
      `worker ${index}:${runList.map((run) => ` ${run.name}@${run.start}-${run.finish}`).join('')}`,
  )
  lines.push(`makespan ${makespan}`)
  return lines
}

function main(argv) {
  const options = parseArguments(argv)
  const graph = parseGraph(readStdin())
  checkAcyclic(graph)
  if (options.mode === 'waves') return renderWaves(graph)
  if (options.mode === 'explain') return renderExplain(graph)
  return renderPack(graph, options.workers)
}

try {
  const lines = main(process.argv.slice(2))
  process.stdout.write(lines.map((line) => `${line}\n`).join(''))
} catch (error) {
  if (error instanceof Error && typeof error.exitCode === 'number') {
    process.stderr.write(`error: ${error.message}\n`)
    process.exit(error.exitCode)
  }
  throw error
}
